parameters.functionCode:
const body = JSON.parse($json.body || '{}');

return [{
  json: {
    email: body.email,
    budget: parseInt(body.budget, 10),
    bedrooms: parseInt(body.bedrooms, 10),
    bathrooms: parseFloat(body.bathrooms),
    location: body.location
  }
}];

const user = $items("Parse Inputs")[0].json;

const filtered = items.filter(i => {
  const row = i.json;
  const price = parseInt(row.price, 10);
  const bedrooms = parseInt(row.bedrooms, 10);
  const bathrooms = parseFloat(row.bathrooms);

  return (
    price >= user.budget - 50000 &&
    price <= user.budget + 100000 &&
    bedrooms === user.bedrooms &&
    bathrooms === user.bathrooms &&
    row.neighborhood.toLowerCase().includes(user.location.toLowerCase())
  );
});

const top3 = filtered.slice(0,3);

return top3.map(f => ({
  json: {
    address: f.json.address,
    price: f.json.price,
    bedrooms: f.json.bedrooms,
    bathrooms: f.json.bathrooms,
    neighborhood: f.json.neighborhood,
    image: f.json.image_url,
    email: user.email
  }
}));

